import java.util.HashMap;
import java.util.Map;

// Assuming the helper is exposed as a static method in the `functions` package
import static functions.RoutingNodesChangedObserver_shardInitialized;

public class ShardNotifier {

    public static void main(String[] args) {
        // Build the payload that the observer expects
        Map<String, String> payload = new HashMap<>();
        payload.put("unassignedShard", "shardA");
        payload.put("initializedShard", "shardB");

        // Notify the routing‑nodes observer
        RoutingNodesChangedObserver_shardInitialized(payload);

        System.out.println("Observer notified: shardA → shardB");
    }
}
```

